import math


def psi(expected, actual, floor=0.0001):
    return sum((actual[k] - expected[k]) * math.log(actual[k] / expected[k]) for k in expected)

exercises.fix_solution:
def distribution_status(value_count: int, total: int, min_pct: float, max_pct: float) -> str:
    """PASS if the value's share is within bounds, WARN if not, NO_DATA if empty."""
    if total == 0:
        return "NO_DATA"
    pct = value_count / total
    return "PASS" if min_pct <= pct <= max_pct else "WARN"
